package stowage

import (
	"strings"
	"sync"
)

// compartment 是舱位的内部记录。
type compartment struct {
	id        string
	maxWeight int64
	cargo     map[string]*cargo
}

// cargo 是货物的内部记录。
type cargo struct {
	id            string
	weight        int64
	destination   string
	allowMixed    bool
	compartmentID string // 空字符串表示未装载
}

// Registry 是舱单与配载的本地登记处。
//
// Registry 的所有方法都可以安全地并发调用。
type Registry struct {
	mu           sync.Mutex
	compartments map[string]*compartment
	cargos       map[string]*cargo
	adjustments  map[string]*AdjustmentResult // 已成功调整的编号 -> 保存的结果快照
	contents     map[string]string            // 已成功调整的编号 -> 规范化内容键
}

// NewRegistry 创建一个空的登记处。
func NewRegistry() *Registry {
	return &Registry{
		compartments: make(map[string]*compartment),
		cargos:       make(map[string]*cargo),
		adjustments:  make(map[string]*AdjustmentResult),
		contents:     make(map[string]string),
	}
}

// RegisterCompartment 登记一个舱位。
// 编号去掉首尾空白后不得为空，maxWeight 必须为正整数（千克）。
// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
func (r *Registry) RegisterCompartment(id string, maxWeight int64) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "舱位编号为空")
	}
	if maxWeight <= 0 {
		return fail(ErrInvalidWeight, cid, "舱位 %s 最大承重必须为正整数千克，当前为 %d", cid, maxWeight)
	}
	if _, exists := r.compartments[cid]; exists {
		return fail(ErrAlreadyExists, cid, "舱位 %s 已存在", cid)
	}
	r.compartments[cid] = &compartment{
		id:        cid,
		maxWeight: maxWeight,
		cargo:     make(map[string]*cargo),
	}
	return nil
}

// RegisterCargo 登记一件货物。
// 编号与目的地去掉首尾空白后不得为空，weight 必须为正整数（千克）。
// 货物登记后处于未装载状态。
// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
func (r *Registry) RegisterCargo(id string, weight int64, destination string, allowMixed bool) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "货物编号为空")
	}
	if weight <= 0 {
		return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
	}
	dest := strings.TrimSpace(destination)
	if dest == "" {
		return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
	}
	if _, exists := r.cargos[cid]; exists {
		return fail(ErrAlreadyExists, cid, "货物 %s 已存在", cid)
	}
	r.cargos[cid] = &cargo{
		id:          cid,
		weight:      weight,
		destination: dest,
		allowMixed:  allowMixed,
	}
	return nil
}

// Compartment 查询舱位的承重、已用重量、剩余重量与货物清单。
// 编号去掉首尾空白后识别；不存在时返回错误。
func (r *Registry) Compartment(id string) (*CompartmentView, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return nil, fail(ErrInvalidID, "", "舱位编号为空")
	}
	comp, ok := r.compartments[cid]
	if !ok {
		return nil, fail(ErrNotFound, cid, "舱位 %s 不存在", cid)
	}
	view := compartmentView(comp)
	return &view, nil
}

// Cargo 查询货物的当前舱位或未装载状态。
// 编号去掉首尾空白后识别；不存在时返回错误。
func (r *Registry) Cargo(id string) (*CargoView, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return nil, fail(ErrInvalidID, "", "货物编号为空")
	}
	c, ok := r.cargos[cid]
	if !ok {
		return nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
	}
	return cargoView(c), nil
}

// sumSet 合计一组货物的重量（调用方持锁）。
func sumSet(set map[string]*cargo) int64 {
	var sum int64
	for _, c := range set {
		sum += c.weight
	}
	return sum
}

// cloneResult 复制一份调整结果，避免调用方修改影响已保存的快照。
func cloneResult(r *AdjustmentResult) *AdjustmentResult {
	return &AdjustmentResult{
		ID:                 r.ID,
		CargoChanges:       append([]CargoChange(nil), r.CargoChanges...),
		CompartmentChanges: append([]CompartmentChange(nil), r.CompartmentChanges...),
	}
}

package stowage

import (
	"math"
	"sort"
)

// cargoView 构造货物快照，重量、目的地与混装许可取登记资料（调用方持锁）。
func cargoView(c *cargo) *CargoView {
	return &CargoView{
		ID:            c.id,
		Weight:        c.weight,
		Destination:   c.destination,
		AllowMixed:    c.allowMixed,
		Loaded:        c.compartmentID != "",
		CompartmentID: c.compartmentID,
	}
}

// compartmentSnapshot 按给定货物集合生成舱位配载快照，是查询实际配载与
// 预览预计配载共用的组装入口：清单按货物编号字典序排列，包含集合中的
// 全部货物；每件货物的重量、目的地与混装许可取登记资料。
//
// projected 为 false 时清单保留货物的真实装载状态与所属舱位（实际配载）；
// 为 true 时一律显示为已装载且属于该舱位（预计配载）。重量合计溢出
// int64 时，已用与剩余重量不提供数值（保持零值），货物清单照常返回。
// 调用方持锁。
func compartmentSnapshot(comp *compartment, set map[string]*cargo, projected bool) CompartmentView {
	ids := make([]string, 0, len(set))
	for cid := range set {
		ids = append(ids, cid)
	}
	sort.Strings(ids)
	views := make([]CargoView, 0, len(ids))
	var used int64
	overflow := false
	for _, cid := range ids {
		c := set[cid]
		view := *cargoView(c)
		if projected {
			// 预计清单中的货物按模拟配载完成后的所属舱位展示；cargoView
			// 返回的是值副本，改写位置字段不影响登记处。
			view.Loaded = true
			view.CompartmentID = comp.id
		}
		views = append(views, view)
		if !overflow {
			if c.weight > math.MaxInt64-used {
				overflow = true
			} else {
				used += c.weight
			}
		}
	}
	view := CompartmentView{
		ID:        comp.id,
		MaxWeight: comp.maxWeight,
		Cargo:     views,
	}
	if !overflow {
		view.UsedWeight = used
		view.RemainingWeight = comp.maxWeight - used
	}
	return view
}

// compartmentView 生成舱位当前实际配载的快照（调用方持锁）。
func compartmentView(comp *compartment) CompartmentView {
	return compartmentSnapshot(comp, comp.cargo, false)
}

// compartmentAfterView 生成舱位在模拟配载下的预计快照（调用方持锁）。
func compartmentAfterView(comp *compartment, set map[string]*cargo) CompartmentView {
	return compartmentSnapshot(comp, set, true)
}

// OpKind 表示调整操作的种类。
type OpKind int

const (
	// OpLoad 装载：将未装载的货物装入目标舱位。
	OpLoad OpKind = iota
	// OpUnload 卸下：将已装载的货物从当前舱位移除，货物记录保留。
	OpUnload
	// OpMove 移动：将已装载的货物直接改放到目标舱位。
	OpMove
)

// String 返回操作种类名称。
func (k OpKind) String() string {
	switch k {
	case OpLoad:
		return "装载"
	case OpUnload:
		return "卸下"
	case OpMove:
		return "移动"
	default:
		return "未知"
	}
}

// Op 是一次调整中的单个操作。
type Op struct {
	Kind    OpKind
	CargoID string
	Target  string // 装载/移动时的目标舱位；卸下时忽略
}

// CargoChange 记录一件货物调整前后的所属舱位。
type CargoChange struct {
	CargoID string
	From    string // 空字符串表示未装载
	To      string // 空字符串表示未装载
}

// CompartmentChange 记录一个舱位调整前后的总重量。
type CompartmentChange struct {
	CompartmentID string
	WeightBefore  int64
	WeightAfter   int64
}

// AdjustmentResult 是一次成功调整的结果快照。
type AdjustmentResult struct {
	ID                 string
	CargoChanges       []CargoChange
	CompartmentChanges []CompartmentChange
}

// CargoView 是货物信息的独立快照。
type CargoView struct {
	ID            string
	Weight        int64
	Destination   string
	AllowMixed    bool
	Loaded        bool
	CompartmentID string // 空字符串表示未装载
}

// CompartmentView 是舱位信息的独立快照。
type CompartmentView struct {
	ID              string
	MaxWeight       int64
	UsedWeight      int64
	RemainingWeight int64
	Cargo           []CargoView // 按编号字典序排列
}

// MixedDestination 描述预计配载中一个舱位内某个目的地对应的全部货物。
type MixedDestination struct {
	Destination string
	CargoIDs    []string // 按编号字典序排列
}

// Rejection 描述预计配载中单个舱位的一条拒绝原因。
//
// Kind 为 ErrOverweight 时，UsedWeight、RemainingWeight、Overweight 与
// MaxWeight 均有效；Kind 为 ErrOverflow（重量溢出）时，预计已用重量、
// 剩余重量与超出量无法用 int64 表示，对应数值字段保持零值，仅提供
// MaxWeight、货物清单与混装原因；Kind 为 ErrMixedLoading 时，
// Destinations 给出各目的地对应的货物，OffendingCargo 列出其中全部
// 不允许混装的货物编号。
type Rejection struct {
	CompartmentID   string
	Kind            ErrorKind
	MaxWeight       int64
	UsedWeight      int64              // 超重时为预计总重量；溢出或混装时为零值
	RemainingWeight int64              // 超重时为预计剩余重量（负值）；其余为零值
	Overweight      int64              // 超重时为超出承重的千克数；其余为零值
	Destinations    []MixedDestination // 混装冲突时各目的地及其货物，按目的地字典序排列
	OffendingCargo  []string           // 混装冲突时全部不允许混装的货物编号，字典序排列
}

// CompartmentPreview 是受影响舱位调整前后的完整配载快照。
// Before 反映调整前配载，清单中的货物保持原所属舱位；After 反映预计
// 配载，清单中的货物一律显示为已装载且属于该舱位，编号、重量、目的地
// 与混装许可仍取登记资料。预计超重时 RemainingWeight 为负值；预计重量
// 溢出 int64 时 After 不提供已用与剩余重量数值（保持零值），货物清单
// 照常返回。
type CompartmentPreview struct {
	ID     string
	Before CompartmentView
	After  CompartmentView
}

// PreviewResult 是一次预览的完整结果，本身是与登记处状态无关的独立快照。
type PreviewResult struct {
	// Submittable 表示按当前登记处状态，这组操作能否作为一次调整提交。
	Submittable bool
	// CargoChanges 列出清单涉及货物的原舱位与预计舱位，按货物编号字典序排列；
	// 未装载用空编号表示。
	CargoChanges []CargoChange
	// Compartments 列出全部受影响舱位调整前后的完整货物清单、已用重量与
	// 剩余重量，按舱位编号字典序排列。即使交换后总重量不变也会列出。
	Compartments []CompartmentPreview
	// Rejections 列出预计配载的全部拒绝原因，按舱位编号排列，同一舱位
	// 先重量（超重/溢出）后混装。为空表示 Submittable 为 true。
	Rejections []Rejection
}

package stowage

import (
	"sort"
)

// Preview 预演一批装载、卸下、移动操作，返回这批安排按当前配载完成后的
// 预计结果。
//
// 预览是只读的：无论结果能否提交，货物位置、舱位占用与已成功调整记录
// 都不会改变，也不占用任何调整编号。清单沿用与 Adjust 相同的 Op 表示
// 与编号规则，逐条合法性（货物与舱位是否存在、货物状态、重复操作、
// 移动到原舱位等）与正式提交完全一致：某条操作不合法时，按输入顺序
// 返回第一个非法操作的现有错误，不返回局部预览。
//
// 每条操作本身合法时始终返回完整预览：预计配载违反承重或混装限制时
// Submittable 为 false，并在 Rejections 中一次列全全部受影响舱位的
// 拒绝原因；判断以整批操作完成后的最终配载为准，不会因中间步骤暂时
// 超重而拒绝最终合法的交换。
//
// 预览反映调用时刻登记处的一致快照（登记、配载与已成功调整记录取自
// 同一时刻，不会混入并发调整前后的状态）。返回内容是独立快照，调用
// 方修改不影响登记处或之后的预览；状态未变时连续预览同一清单结果
// 一致。正式提交仍以提交时状态重新判断，不能凭旧预览直接放行。
func (r *Registry) Preview(ops []Op) (*PreviewResult, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if len(ops) == 0 {
		return nil, fail(ErrEmptyAdjustment, "", "预览清单不包含任何操作")
	}

	// 与正式提交共用同一套逐条校验与最终配载模拟；预览不带调整编号。
	vops, final, affected, err := r.prepareOps(ops, fail)
	if err != nil {
		return nil, err
	}

	// 涉及货物的原舱位与预计舱位，按货物编号字典序排列。
	cargoChanges := make([]CargoChange, 0, len(vops))
	for _, v := range vops {
		c := v.cargo
		change := CargoChange{CargoID: c.id, From: c.compartmentID}
		switch v.op.Kind {
		case OpLoad, OpMove:
			change.To = v.target.id
		case OpUnload:
			change.To = ""
		}
		cargoChanges = append(cargoChanges, change)
	}
	sort.Slice(cargoChanges, func(i, j int) bool {
		return cargoChanges[i].CargoID < cargoChanges[j].CargoID
	})

	// 受影响舱位调整前后的完整配载，按舱位编号字典序排列。交换中总重量
	// 不变的两个舱位同样列出。
	compIDs := make([]string, 0, len(affected))
	for id := range affected {
		compIDs = append(compIDs, id)
	}
	sort.Strings(compIDs)
	compartments := make([]CompartmentPreview, 0, len(compIDs))
	for _, id := range compIDs {
		compartments = append(compartments, CompartmentPreview{
			ID:     id,
			Before: compartmentView(r.compartments[id]),
			After:  compartmentAfterView(r.compartments[id], final[id]),
		})
	}

	// 预计配载的全部拒绝原因，按舱位编号排列、同舱先重量后混装。
	rejs := r.evaluateFinal(final)
	sort.SliceStable(rejs, func(i, j int) bool {
		if rejs[i].CompartmentID != rejs[j].CompartmentID {
			return rejs[i].CompartmentID < rejs[j].CompartmentID
		}
		return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
	})
	rejections := make([]Rejection, 0, len(rejs))
	for _, rej := range rejs {
		rejections = append(rejections, *cloneRejection(rej))
	}

	return &PreviewResult{
		Submittable:  len(rejections) == 0,
		CargoChanges: cargoChanges,
		Compartments: compartments,
		Rejections:   rejections,
	}, nil
}

// cloneRejection 复制拒绝原因中的切片，保证调用方修改不影响其他结果。
func cloneRejection(x *Rejection) *Rejection {
	cp := &Rejection{
		CompartmentID:   x.CompartmentID,
		Kind:            x.Kind,
		MaxWeight:       x.MaxWeight,
		UsedWeight:      x.UsedWeight,
		RemainingWeight: x.RemainingWeight,
		Overweight:      x.Overweight,
	}
	if x.Destinations != nil {
		cp.Destinations = make([]MixedDestination, len(x.Destinations))
		for i, d := range x.Destinations {
			cp.Destinations[i] = MixedDestination{
				Destination: d.Destination,
				CargoIDs:    append([]string(nil), d.CargoIDs...),
			}
		}
	}
	if x.OffendingCargo != nil {
		cp.OffendingCargo = append([]string(nil), x.OffendingCargo...)
	}
	return cp
}

package stowage

import "strings"

// AmendCargo 按货物编号更正一件货物的重量、目的地与混装许可。
//
// 编号与目的地沿用登记规则：去掉首尾空白后不得为空，编号区分大小写；
// weight 必须为正整数（千克）。空编号、货物不存在、非正重量或去空白后
// 目的地为空都按现有结构化错误拒绝；修改不存在的货物不会变成登记。
//
// 三项资料作为一次完整替换生效，内容与现有资料完全相同时同样成功，
// 但不新增货物、不再次占用重量。更正不占用配载调整编号，也不影响已
// 成功调整保存的结果：之后以原编号、原内容重复提交调整，仍返回首次
// 成功时的变化与重量。更正前返回的查询或预览快照继续保留原内容。
//
// 未装载货物只需资料本身合法，更正后仍为未装载。已装载货物按三项新
// 资料共同生效后的最终配载判断，不会因修改某个字段的中间状态不合法
// 而拒绝最终合法的资料：所属舱位先扣除该货物旧重量、再计入新重量，
// 恰好达到承重允许保存，超过承重或合计无法用 int64 表示则拒绝；
// 同舱目的地全部相同时允许不混装的货物共舱，出现不同目的地时所有
// 货物都必须允许混装。
//
// 更正失败时，货物的三项旧资料、所属舱位重量及其他货物全部保留。
func (r *Registry) AmendCargo(id string, weight int64, destination string, allowMixed bool) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "货物编号为空")
	}
	c, ok := r.cargos[cid]
	if !ok {
		return fail(ErrNotFound, cid, "货物 %s 不存在", cid)
	}
	if weight <= 0 {
		return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
	}
	dest := strings.TrimSpace(destination)
	if dest == "" {
		return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
	}

	// 已装载货物：在所属舱位的模拟配载上替换该货物，按三项资料共同
	// 生效后的最终状态统一判断，而不是逐个字段制造中间状态。
	if c.compartmentID != "" {
		comp := r.compartments[c.compartmentID]
		sim := &cargo{
			id:            c.id,
			weight:        weight,
			destination:   dest,
			allowMixed:    allowMixed,
			compartmentID: comp.id,
		}
		set := make(map[string]*cargo, len(comp.cargo))
		for otherID, other := range comp.cargo {
			if otherID == c.id {
				set[c.id] = sim
			} else {
				set[otherID] = other
			}
		}
		final := map[string]map[string]*cargo{comp.id: set}
		if rej := r.firstRejection(final); rej != nil {
			switch rej.Kind {
			case ErrOverflow:
				return fail(ErrOverflow, comp.id, "舱位 %s 重量合计超过 int64 可表示范围", comp.id)
			case ErrOverweight:
				return fail(ErrOverweight, comp.id,
					"舱位 %s 总重量 %d 千克超过最大承重 %d 千克",
					comp.id, rej.UsedWeight, comp.maxWeight)
			default:
				return fail(ErrMixedLoading, rej.firstOffender(),
					"舱位 %s 存在不同目的地货物，但货物 %s 不允许混装",
					comp.id, rej.firstOffender())
			}
		}
	}

	c.weight = weight
	c.destination = dest
	c.allowMixed = allowMixed
	return nil
}

