// assertAllEmpty 确认四件货物都未装载、两个舱位都是空舱。
func assertAllEmpty(t *testing.T, r *Registry) {
	t.Helper()
	for _, id := range []string{"G1", "G2", "G3", "G4"} {
		c, _ := r.Cargo(id)
		if c.Loaded || c.CompartmentID != "" {
