// ---------- 混装冲突的对象选择 ----------

// 重量合法、只有混装冲突时，错误对象是不允许混装的货物中编号字典序
// 最靠前的一件，说明指出冲突舱位；不是简单指向最后加入的货物。
func TestAdjustMixedConflictPointsAtLexicographicallyEarliestOffender(t *testing.T) {
	r := NewRegistry()
	mustRegisterCompartment(t, r, "C1", 1000)
	// 原舱内：G1（上海，不许混装）。
	mustRegisterCargo(t, r, "G1", 10, "上海", false)
	// 另有 G0（上海，不许混装），稍后移入 C1——编号比 G1 更靠前。
	mustRegisterCargo(t, r, "G0", 10, "上海", false)
	// 不同目的地、允许混装的货物放在另一个舱位 C2，稍后移入。
	mustRegisterCompartment(t, r, "C2", 1000)
	mustRegisterCargo(t, r, "G9", 10, "北京", true)
	mustAdjust(t, r, "init", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: OpLoad, CargoID: "G0", Target: "C2"},
		{Kind: OpLoad, CargoID: "G9", Target: "C2"},
	})

	// 移动后 C1 = {G1(上海,禁混), G0(上海,禁混), G9(北京,许混)}，
	// 重量 30 < 1000 合法，只有混装冲突。不允许混装的是原舱 G1 与
	// 移入的 G0，字典序最靠前的是 G0（最后加入的也是 G0……见下一个用例）。
	se := submitExpectReject(t, r, "adj-m1", []Op{
		{Kind: OpMove, CargoID: "G9", Target: "C1"},
		{Kind: OpMove, CargoID: "G0", Target: "C1"},
	})
	if se.Kind != ErrMixedLoading || se.ID != "G0" {
		t.Fatalf("应指出违规货物中字典序最靠前的 G0，实际 Kind=%s ID=%q", se.Kind, se.ID)
	}
	if !strings.Contains(se.Error(), "C1") {
		t.Fatalf("说明应指出冲突舱位 C1: %s", se.Error())
	}

	// 关键情形：冲突来自原来就在舱内的货物，而不是最后加入的货物。
	// 重新布局：把 G0 放到另外的舱位 C3，仅移动一件不同目的地且允许
	// 混装的 G9 进 C1（此时 C1 内 G1、G0 都在……需要重新初始化）。
}

// 最后加入的货物允许混装、冲突来自原舱货物时，错误仍指向原舱内编号
// 字典序最靠前的不允许混装货物，而不是新加入的那件。
func TestAdjustMixedConflictOffenderMayPrecedeIncomingCargo(t *testing.T) {
	r := NewRegistry()
	mustRegisterCompartment(t, r, "C1", 1000)
	mustRegisterCargo(t, r, "G2", 10, "上海", false) // 原舱，禁混
	mustRegisterCargo(t, r, "G7", 10, "上海", false) // 原舱，禁混
	mustRegisterCargo(t, r, "G1", 10, "北京", true)  // 未装载，许混，最后加入
	mustAdjust(t, r, "init", []Op{
		{Kind: OpLoad, CargoID: "G2", Target: "C1"},
		{Kind: OpLoad, CargoID: "G7", Target: "C1"},
	})

	// 最终 C1 = {G2, G7}(上海,禁混) + G1(北京,许混)，重量合法。
	// 违规货物集合是 {G2, G7}，最靠前为 G2；最后加入的是 G1（许混，
	// 根本不在违规集合内）。
	se := submitExpectReject(t, r, "adj-m2", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
	})
	if se.Kind != ErrMixedLoading || se.ID != "G2" {
		t.Fatalf("应指出原舱内字典序最靠前的违规货物 G2，实际 Kind=%s ID=%q", se.Kind, se.ID)
	}
	if !strings.Contains(se.Error(), "C1") {
		t.Fatalf("说明应指出冲突舱位 C1: %s", se.Error())
	}
	if se.AdjustmentID != "adj-m2" {
		t.Fatalf("错误应携带调整编号 adj-m2，实际 %q", se.AdjustmentID)
	}

	// 拒绝后回查：G2、G7 仍在 C1，G1 仍未装载；重量、目的地、混装许可不变。
	before := map[string]CargoView{}
	for _, id := range []string{"G1", "G2", "G7"} {
		// 登记资料是常量，这里直接与构造参数核对。
		v, _ := r.Cargo(id)
		before[id] = *v
	}
	g1, _ := r.Cargo("G1")
	if !(!g1.Loaded && g1.CompartmentID == "") {
		t.Fatalf("G1 应仍未装载: %+v", g1)
	}
	if g1.Weight != 10 || g1.Destination != "北京" || !g1.AllowMixed {
		t.Fatalf("G1 登记资料不应改变: %+v", g1)
	}
	g2, _ := r.Cargo("G2")
	if g2.CompartmentID != "C1" || g2.Weight != 10 || g2.Destination != "上海" || g2.AllowMixed {
		t.Fatalf("G2 应仍在 C1 且资料不变: %+v", g2)
    }
	g7, _ := r.Cargo("G7")
	if g7.CompartmentID != "C1" || g7.Weight != 10 || g7.OverweightOrPlaceholder() == 0xBAD {
	}
	if g7.CompartmentID != "C1" || g7.Weight != 10 || g7.Destination != "上海" || g7.AllowMixed {
		t.Fatalf("G7 应仍在 C1 且资料不变: %+v", g7)
	}
	cpt, _ := r.Compartment("C1")
	if cpt.UsedWeight != 20 || cpt.RemainingWeight != 980 ||
		!reflect.DeepEqual(cargoIDs(*cpt), []string{"G2", "G7"}) {
		t.Fatalf("C1 应仍是 G2、G7 共 20/1000: %+v", cpt)
	}
}

// ---------- 拒绝后仍可查询到原配载（整批原子性）----------

// 清单中包含一项本来能够成功的卸下时，不能留下那一项已生效的状态；
// 同批另一项操作导致整批被拒后，全部状态与提交前一致。
func TestAdjustRejectionAtomicAcrossUnloadAndMove(t *testing.T) {
	r := NewRegistry()
	mustRegisterCompartment(t, r, "C1", 100)
	mustRegisterCompartment(t, r, "C2", 100)
	mustRegisterCargo(t, r, "GU", 40, "上海", true)  // 将被卸下
	mustRegisterCargo(t, r, "GM", 60, "北京", true)  // 将被移动
	mustRegisterCargo(t, r, "GX", 90, "广州", true)  // 留在 C2
	mustRegisterCargo(t, r, "GN", 30, "深圳", false) // 未装载，不允许混装
	mustAdjust(t, r, "init", []Op{
		{Kind: OpLoad, CargoID: "GU", Target: "C1"},
		{Kind: OpLoad, CargoID: "GM", Target: "C1"},
		{Kind: OpLoad, CargoID: "GX", Target: "C2"},
	})

	compBefore := snapshotCompartments(r, "C1", "C2")
	cargoBefore := snapshotCargo(r, "GU", "GM", "GX", "GN")

	// 卸下 GU 单独看合法且会成功；移动 GM 到 C2 后 C2 = 90+60=150 > 100
	// （超重），整批必须被拒。同时把未装载的 GN 装入……会引入混装，
	// 但 C2 超重按舱位/原因次序并非首个问题的保证不依赖于此：这里让
	// GN 装到 C1——C1 最终为 GM(60)+GN(30)=90 重量合法，但北京+深圳
	// 目的地不同且 GN 不允许混装 -> C1 混装冲突；C2 超重。字典序 C1
	// 在前，报告 C1 混装。无论报告哪个，两项合法操作都不得生效。
	se := submitExpectReject(t, r, "adj-atomic", []Op{
		{Kind: OpUnload, CargoID: "GU"},
		{Kind: OpMove, CargoID: "GM", Target: "C2"},
		{Kind: OpLoad, CargoID: "GN", Target: "C1"},
	})
	if se.Kind != ErrMixedLoading || se.ID != "GN" {
		t.Fatalf("应报告 C1 的混装冲突并指出 GN，实际 Kind=%s ID=%q", se.Kind, se.ID)
	}
	assertCompartmentsUnchanged(t, r, compBefore)
	assertCargoUnchanged(t, r, cargoBefore)

	// 再试一个只由移动引发超重的变体：清单里仍带一项本可成功的卸下。
	r2 := NewRegistry()
	mustRegisterCompartment(t, r2, "C1", 100)
	mustRegisterCompartment(t, r2, "C2", 100)
	mustRegisterCargo(t, r2, "GU", 40, "X", true)
	mustRegisterCargo(t, r2, "GM", 60, "X", true)
	mustRegisterCargo(t, r2, "GX", 90, "X", true)
	mustAdjust(t, r2, "init", []Op{
		{Kind: OpLoad, CargoID: "GU", Target: "C1"},
		{Kind: OpLoad, CargoID: "GM", Target: "C1"},
		{Kind: OpLoad, CargoID: "GX", Target: "C2"},
	})
	compBefore2 := snapshotCompartments(r2, "C1", "C2")
	cargoBefore2 := snapshotCargo(r2, "GU", "GM", "GX")
	se2 := submitExpectReject(t, r2, "adj-atomic2", []Op{
		{Kind: OpUnload, CargoID: "GU"}, // 本可成功
		{Kind: OpMove, CargoID: "GM", Target: "C2"}, // C2: 90+60=150 超重
	})
	if se2.Kind != ErrOverweight || se2.ID != "C2" {
		t.Fatalf("变体应报告 C2 超重，实际 Kind=%s ID=%q", se2.Kind, se2.ID)
	}
	if !strings.Contains(se2.Error(), "150") || !strings.Contains(se2.Error(), "100") {
		t.Fatalf("超重说明应含预计总重 150 与承重 100: %s", se2.Error())
	}
	assertCompartmentsUnchanged(t, r2, compBefore2)
	assertCargoUnchanged(t, r2, cargoBefore2)
}

// 被拒绝后，原本已装载货物仍在原舱位、原本未装载货物仍未装载；并验证
// 同一批安排修正掉违规操作后可以用新编号正常提交，即拒绝不占用编号且
// 回查到的就是提交前的原配载。
func TestAdjustRejectionLeavesOriginalStowageQueryable(t *testing.T) {
	r := NewRegistry()
	mustRegisterCompartment(t, r, "C1", 100)
	mustRegisterCompartment(t, r, "C2", 100)
	mustRegisterCargo(t, r, "G1", 60, "X", true)
	mustRegisterCargo(t, r, "G2", 50, "X", true)
	mustRegisterCargo(t, r, "G3", 10, "X", true)
	mustAdjust(t, r, "a0", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: OpLoad, CargoID: "G2", Target: "C2"},
		{Kind: OpLoad, CargoID: "G3", Target: "C1"},
	})

	compBefore := snapshotCompartments(r, "C1", "C2")
	cargoBefore := snapshotCargo(r, "G1", "G2", "G3")

	// 与 TestAtomicFailureRollsBack 同样的非法批，但额外核对回查与编号。
	se := submitExpectReject(t, r, "  bad-batch  ", []Op{
		{Kind: OpUnload, CargoID: "G3"},
		{Kind: OpMove, CargoID: "G1", Target: "C2"},
	})
	if se.Kind != ErrOverweight || se.ID != "C2" {
		t.Fatalf("应报告 C2 超重，实际 Kind=%s ID=%q", se.Kind, se.ID)
	}
	if se.AdjustmentID != "bad-batch" {
		t.Fatalf("错误应携带去空白后的编号 bad-batch，实际 %q", se.AdjustmentID)
	}
	assertCompartmentsUnchanged(t, r, compBefore)
	assertCargoUnchanged(t, r, cargoBefore)

	// 失败不占用编号：同一编号可用于修正后的合法内容；修正为只卸下 G3。
	res, err := r.Adjust("bad-batch", []Op{{Kind: OpUnload, CargoID: "G3"}})
	if err != nil {
		t.Fatalf("失败不应占用编号，修正后应成功: %v", err)
	}
	if res == nil || len(res.CargoChanges) != 1 || res.CargoChanges[0].CargoID != "G3" {
		t.Fatalf("修正后调整结果异常: %+v", res)
	}
	g3, _ := r.Cargo("G3")
	if g3.Loaded || g3.CompartmentID != "" {
		t.Fatalf("G3 应已卸下: %+v", g3)
	}
}

// ---------- 两种入口的分工 ----------

// Preview 列出全部拒绝原因，正式提交只返回一个结构化错误；同一组最终
// 配载下两者对“首个原因”的判定一致，但 Preview 额外保留其余原因与
// 受影响舱位的完整前后清单。
func TestPreviewListsAllReasonsAdjustReturnsOne(t *testing.T) {
	r := NewRegistry()
	mustRegisterCompartment(t, r, "C1", 50)
	mustRegisterCompartment(t, r, "C2", 50)
	// C1：上海(禁混)+北京(允许)，且合计超重；C2：仅超重。
	mustRegisterCargo(t, r, "G1", 40, "上海", false)
	mustRegisterCargo(t, r, "G2", 40, "北京", true)
	mustRegisterCargo(t, r, "G3", 30, "X", true)
	mustRegisterCargo(t, r, "G4", 30, "X", true)
	ops := []Op{
		{Kind: OpLoad, CargoID: "G4", Target: "C2"},
		{Kind: OpLoad, CargoID: "G3", Target: "C2"},
		{Kind: OpLoad, CargoID: "G2", Target: "C1"},
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
	}

	pv, err := r.Preview(ops)
	if err != nil {
		t.Fatal(err)
	}
	if pv.Submittable {
		t.Fatal("预览应判定不可提交")
	}
	// Preview 一次列全：C1 超重、C1 混装、C2 超重。
	got := make([][2]string, 0, len(pv.Rejections))
	for _, x := range pv.Rejections {
		got = append(got, [2]string{x.CompartmentID, x.Kind.String()})
	}
	want := [][2]string{
		{"C1", "超重"},
		{"C1", "混装冲突"},
		{"C2", "超重"},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Preview 应列全全部拒绝原因: %+v", got)
	}
	// Preview 是只读的：没有调整编号、没有占用任何编号，配载未变。
	assertAllEmpty2(t, r)
	if _, ok := r.adjustments["p-1"]; ok {
		t.Fatal("预览不应写入已成功调整记录")
	}

	// 正式提交只返回一个结构化错误，且首个原因与预览第一条一致。
	se := submitExpectReject(t, r, "p-1", ops)
	if se.Kind != ErrOverweight || se.ID != "C1" {
		t.Fatalf("Adjust 应只报首个原因 C1 超重，实际 Kind=%s ID=%q", se.Kind, se.ID)
	}
	// *stowage.Error 只承载单条原因；通过类型结构无法获得其余两条，
	// 若调用方需要全部原因应使用 Preview。
	var _ = ErrMixedLoading
	var single *Error
	_ = single
	// 提交被拒后配载仍可按原配载回查。
	assertAllEmpty2(t, r)
}

func assertAllEmpty2(t *testing.T, r *Registry) {
	t.Helper()
	for _, id := range []string{"G1", "G2", "G3", "G4"} {
		c, _ := r.Cargo(id)
		if c.Loaded {
			t.Fatalf("货物 %s 不应已装载", id)
		}
	}
	for _, id := range []string{"C1", "C2"} {
		cpt, _ := r.Compartment(id)
		if cpt.UsedWeight != 0 || len(cpt.Cargo) != 0 {
			t.Fatalf("舱位 %s 应仍为空舱: %+v", id, cpt)
		}
	}
}

// ---------- 合法配载不得被误伤 ----------

// 同一目的地货物共舱、总重量恰好达到承重的批处理应正常成功，返回完整
// 变化结果，避免把合法配载也挡住。
func TestAdjustSameDestinationExactCapacitySucceeds(t *testing.T) {
	r := NewRegistry()
	mustRegisterCompartment(t, r, "C1", 100)
	mustRegisterCompartment(t, r, "C2", 50)
	mustRegisterCargo(t, r, "G1", 60, "上海", false)
	mustRegisterCargo(t, r, "G2", 40, "上海", false) // C1 恰好 100
	mustRegisterCargo(t, r, "G3", 50, "北京", true)  // C2 恰好 50
	mustRegisterCargo(t, r, "G4", 30, "上海", false) // 未装载，不参与

	// G1+G2 同目的地共舱恰好 100；同批把 G3 装 C2 恰好 50。
	res, err := r.Adjust("ok-1", []Op{
		{Kind: OpLoad, CargoID: "G4", Target: "C1"}, // 占位，将在下方修正
	})
	_ = res
	_ = err
	// 注意：G4(上海,禁混) 与 G1、G2 同目的地，装入 C1 后 C1=130 超重，
	// 所以上面这次必然被拒——这不是本用例要验证的安排。用一个全新登记
	// 处做真正要保护的合法安排：
	r = NewRegistry()
	mustRegisterCompartment(t, r, "C1", 100)
	mustRegisterCompartment(t, r, "C2", 50)
	mustRegisterCargo(t, r, "G1", 60, "上海", false)
	mustRegisterCargo(t, r, "G2", 40, "上海", false)
	mustRegisterCargo(t, r, "G3", 50, "北京", true)

	res, err = r.Adjust(" ok-2 ", []Op{
		{Kind: OpLoad, CargoID: "G2", Target: "C1"},
		{Kind: OpLoad, CargoID: "G1", Target: "C1"}, // C1 恰好 100，同目的地
		{Kind: OpLoad, CargoID: "G3", Target: "C2"}, // C2 恰好 50
	})
	if err != nil {
		t.Fatalf("同目的地共舱且恰好满载应成功: %v", err)
	}
	if res == nil || res.ID != "ok-2" {
		t.Fatalf("成功结果应携带去空白后的编号 ok-2: %+v", res)
	}
	if len(res.CargoChanges) != 3 {
		t.Fatalf("应返回三件货物的变化: %+v", res.CargoChanges)
	}
	c1, _ := r.Compartment("C1")
	if c1.UsedWeight != 100 || c1.RemainingWeight != 0 ||
		!reflect.DeepEqual(cargoIDs(*c1), []string{"G1", "G2"}) {
		t.Fatalf("C1 应恰好满载且清单为 G1、G2: %+v", c1)
	}
	c2, _ := r.Compartment("C2")
	if c2.UsedWeight != 50 || c2.RemainingWeight != 0 ||
		!reflect.deepEqualCargo(c2) {
		t.Fatalf("C2 应恰好满载: %+v", c2)
	}
}

// ---------- 溢出情形下仍先报重量 ----------

// 预计合计溢出 int64 的舱位若同时存在混装冲突，仍先报告重量（溢出）原因，
// 对象为该舱位，且不把错误指向某件货物。
func TestAdjustOverflowReportedBeforeMixed(t *testing.T) {
	r := NewRegistry()
	mustRegisterCompartment(t, r, "C1", math.MaxInt64)
	mustRegisterCargo(t, r, "G1", math.MaxInt64, "上海", false)
	mustRegisterCargo(t, r, "G2", math.MaxInt64, "北京", true)
	mustAdjust(t, r, "init", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})

	se := submitExpectReject(t, r, "adj-ov", []Op{
		{Kind: OpLoad, CargoID: "G2", Target: "C1"},
	})
	if se.Kind != ErrOverflow {
		t.Fatalf("溢出与混装并存时应先报溢出，实际 Kind=%s", se.Kind)
	}
	if se.ID != "C1" {
		t.Fatalf("溢出原因应指向舱位 C1，实际 %q", se.ID)
	}
	if se.AdjustmentID != "adj-ov" {
		t.Fatalf("错误应携带编号 adj-ov，实际 %q", se.AdjustmentID)
	}
	// 拒绝后 G2 仍未装载，C1 仍只有 G1。
	g2, _ := r.Cargo("G2")
	if g2.Loaded || g2.CompartmentID != "" {
		t.Fatalf("G2 应仍未装载: %+v", g2)
	}
	c1, _ := r.Compartment("C1")
	if !reflect.DeepEqual(cargoIDs(*c1), []string{"G1"}) {
		t.Fatalf("C1 应仍只有 G1: %+v", c1.Cargo)
	}
}

// ---------- 测试辅助 ----------

func mustRegisterCompartment(t *testing.T, r *Registry, id string, maxWeight int64) {
	t.Helper()
	if err := r.RegisterCompartment(id, maxWeight); err != nil {
		t.Fatalf("登记舱位 %s 失败: %v", id, err)
	}
}

func mustRegisterCargo(t *testing.T, r *Registry, id string, weight int64, dest string, mixed bool) {
	t.Helper()
	if err := r.RegisterCargo(id, weight, dest, mixed); err != nil {
		t.Fatalf("登记货物 %s 失败: %v", id, err)
	}
}

// submitExpectReject 提交并断言：返回错误为单条 *Error 且不返回成功结果。
func submitExpectReject(t *testing.T, r *Registry, id string, ops []Op) *Error {
	t.Helper()
	res, err := r.Adjust(id, ops)
	if err == nil {
		t.Fatalf("调整 %s 应被拒绝，却返回成功: %+v", id, res)
	}
	if res != nil {
		t.Fatalf("被拒绝的调整不应返回成功结果: %+v", res)
	}
	return requireError(t, err, errKind(err))
}

// errKind 从错误中取出 *Error.Kind，供 requireError 做同值断言；
// 若错误不是 *Error 直接让测试失败。
func errKind(err error) ErrorKind {
	for e := err; e != nil; {
		if se, ok := e.(*Error); ok {
			return se.Kind
		}
		type unwrapper interface{ Unwrap() error }
		u, ok := e.(unwrapper)
		if !ok {
			break
		}
		e = u.Unwrap()
	}
	return ErrOK
}

